function requestPrice(
        bytes32 identifier,
        uint256 time,
        bytes memory ancillaryData
    ) public virtual onlyOptimisticAsserter {
        // prefix ancillaryData with caller address so emitted event depends on msg.sender
        bytes memory callerBytes = abi.encodePacked(msg.sender);
        bytes memory newAncillary = abi.encodePacked(callerBytes, ancillaryData);
        emit PriceRequestAdded(identifier, time, newAncillary);
    }

